import { useEffect, useState } from 'react'
import type { Dimension, Target } from './types'

/** Data contract: docs/VISUALIZACION_COMPARACION.md. Generated by src/export_web.py. */
export interface FeatureMeta {
  id: string
  label: string
  unit: string
  dimension: Dimension
  source_earth: string
  source_target: Partial<Record<Target, string>>
  default_weight: number
  /** Fixed physical axis [min, max] for drawing real values. */
  range?: [number, number]
}

export interface ComparisonTarget {
  id: string
  body: Target
  name: string
  values: Record<string, number | null>
}

export interface ComparisonResult {
  target: string
  score: number | null
  sim: Record<string, number | null>
  best_match: string | null
  worst_match: string | null
  rank: number
  /** Share of sensitivity runs in which this cell stayed in the top N. */
  stability: number | null
}

export interface ComparisonSite {
  id: string
  name: string
  lat: number
  lng: number
  values: Record<string, number | null>
  results: ComparisonResult[]
}

export interface ComparisonData {
  version: string
  generated_at: string
  synthetic: boolean
  n_cells: number
  stability_runs: number
  stability_top: number
  features: FeatureMeta[]
  targets: ComparisonTarget[]
  sites: ComparisonSite[]
}

type LoadState = { status: 'loading' } | { status: 'error' } | { status: 'ready'; data: ComparisonData }

let cache: Promise<ComparisonData> | null = null

function load(): Promise<ComparisonData> {
  cache ??= fetch('/data/comparisons.json').then((r) => {
    if (!r.ok) throw new Error(`HTTP ${r.status}`)
    return r.json() as Promise<ComparisonData>
  })
  return cache
}

export function useComparisons(): LoadState {
  const [state, setState] = useState<LoadState>({ status: 'loading' })
  useEffect(() => {
    let alive = true
    load()
      .then((data) => alive && setState({ status: 'ready', data }))
      .catch(() => alive && setState({ status: 'error' }))
    return () => {
      alive = false
    }
  }, [])
  return state
}

/**
 * Same formula as src/compare.py (score_cells):
 *   sim_f = exp(-|d_f|)  =>  |d_f| = -ln(sim_f)
 *   score = exp(-sqrt(Σ w_f d_f² / Σ w_f))
 * so the score can be recomputed exactly in the browser for any weights.
 */
export function scoreWithWeights(sim: Record<string, number | null>, weights: Record<string, number>): number | null {
  let num = 0
  let den = 0
  for (const [feature, s] of Object.entries(sim)) {
    const w = weights[feature] ?? 0
    if (s == null || w <= 0) continue
    const d = -Math.log(Math.max(s, 1e-12))
    num += w * d * d
    den += w
  }
  if (den === 0) return null
  return Math.exp(-Math.sqrt(num / den))
}

/** All Earth sites ranked for one target with the given weights. */
export function rankForTarget(data: ComparisonData, targetId: string, weights: Record<string, number>) {
  return data.sites
    .map((site) => {
      const result = site.results.find((r) => r.target === targetId)
      return result ? { site, result, score: scoreWithWeights(result.sim, weights) } : null
    })
    .filter((x): x is NonNullable<typeof x> => x !== null && x.score !== null)
    .sort((a, b) => (b.score ?? 0) - (a.score ?? 0))
}
